"""Offline matched-sample renewable checks, regenerated by run_all.py.

Two-factor full quadratics only. Week/month folds refit response transforms,
coding and smearing on training data. Realized covariates make these explanatory
diagnostics, not operational forecasts. No model selection or network access.
"""
from pathlib import Path

import numpy as np
import pandas as pd

from config import CONFIG
from ingest import write_json
from rsr import Surface, block_index

FACTORS = {'gross': 'sys_load_peak_norm', 'net': 'sys_net_load_peak_norm',
           'wind_only': 'wind_peak_norm', 'solar_only': 'solar_peak_norm'}


def fit_surface(d: pd.DataFrame, model: str, response: str):
    d = d.copy()
    raw = d['spread_mean'] if response == 'level' else d['spread_sd']
    if response == 'level':
        med = float(raw.median())
        mad = float((raw-med).abs().median())
        if not mad > 0:
            raise ValueError('Training response MAD is zero')
        d['y'] = np.arcsinh((raw-med)/mad)
        info = {'median': med, 'mad': mad}
    else:
        if not (raw > 0).all():
            raise ValueError('Volatility response must be positive')
        d['y'] = np.log(raw)
        info = {}
    s = Surface(d, response='y', factors=['sys_temp', FACTORS[model]], labels=['T', 'L'],
                block=['post_rtcb'], date='local_date', settings=CONFIG['rsr'])
    return s, s.full(), info


def heldout(d: pd.DataFrame, model: str, response: str, kind: str) -> pd.DataFrame:
    d = d.sort_values('local_date').reset_index(drop=True)
    groups = ((d.local_date-pd.Timestamp(CONFIG['study']['start'])).dt.days//7).to_numpy() if kind == 'week' \
        else d.local_date.dt.to_period('M').astype(str).to_numpy()
    pred, ty, tp, tb = (np.full(len(d), np.nan) for _ in range(4))
    raw = d['spread_mean' if response == 'level' else 'spread_sd'].to_numpy()
    for group in np.unique(groups):
        test = groups == group
        s, fit, info = fit_surface(d.loc[~test], model, response)
        X = s.design(fit.terms, Z=s.coding.code(d.loc[test, s.factors].to_numpy()),
                     B=d.loc[test, ['post_rtcb']].to_numpy())
        yh = X.to_numpy() @ fit.params.to_numpy()
        if response == 'level':
            pred[test] = info['median'] + info['mad'] * np.sinh(yh[:, None]+fit.resid.to_numpy()).mean(axis=1)
            ty[test] = np.arcsinh((raw[test]-info['median'])/info['mad'])
        else:
            pred[test] = np.exp(yh)*np.exp(fit.resid.to_numpy()).mean()
            ty[test] = np.log(raw[test])
        tp[test], tb[test] = yh, s.y.mean()
    if not np.isfinite(pred).all():
        raise ValueError('Nonfinite held-out predictions')
    return pd.DataFrame({'local_date': d.local_date, 'actual_dollars': raw, 'predicted_dollars': pred,
                         'transformed_actual': ty, 'transformed_prediction': tp, 'training_mean': tb, 'fold': groups})


def scores(pred: pd.DataFrame) -> dict:
    y, p = pred.actual_dollars.to_numpy(), pred.predicted_dollars.to_numpy()
    return {'n_scored': len(y), 'dollar_mae': float(np.mean(abs(y-p))),
            'dollar_rmse': float(np.sqrt(np.mean((y-p)**2))),
            'dollar_r2': float(1-np.sum((y-p)**2)/np.sum((y-y.mean())**2)),
            'transformed_skill': float(1-np.sum((pred.transformed_actual-pred.transformed_prediction)**2)
                                      / np.sum((pred.transformed_actual-pred.training_mean)**2))}


def paired_mae(a: pd.DataFrame, b: pd.DataFrame) -> dict:
    if not a.local_date.equals(b.local_date):
        raise ValueError('Paired losses require identical dates')
    delta = abs(a.actual_dollars-a.predicted_dollars).to_numpy()-abs(b.actual_dollars-b.predicted_dollars).to_numpy()
    rng = np.random.default_rng(CONFIG['inference']['seed'])
    draws = np.array([delta[block_index(len(delta), 25, rng)].mean() for _ in range(1999)])
    return {'mae_reduction': float(delta.mean()), 'ci_low': float(np.quantile(draws, .025)),
            'ci_high': float(np.quantile(draws, .975))}


def write_checks(out: Path) -> None:
    daily = pd.read_parquet(CONFIG['paths']['processed']/'daily.parquet')
    d = daily[daily.zone == 'SYSTEM'].copy()
    if 'sys_net_load_peak_norm' not in d or d.sys_net_load_peak_norm.isna().all():
        print('Renewable checks skipped: both actual-generation inputs are needed.')
        return
    h = pd.read_parquet(CONFIG['paths']['processed']/'hourly_features.parquet').drop_duplicates('hour_utc')
    for component in ('wind', 'solar'):
        values = h.sys_load-h[f'{component}_gen']
        reference = values.quantile(CONFIG['features']['load_norm_quantile'])
        peaks = values.groupby(h.local_date).max()/reference
        d[f'{component}_peak_norm'] = d.local_date.map(peaks)
    baseline = d.complete_day & d.factors_complete
    keep = baseline & d.sys_net_load_peak_norm.notna()
    write_json(out/'renewable_coverage.json', {
        'baseline_days': int(baseline.sum()), 'matched_days': int(keep.sum()),
        'additional_exclusions': [str(x.date()) for x in d.loc[baseline & ~keep, 'local_date']],
        'missing_generation': {c: [str(x) for x in h.loc[h[c].isna(), 'hour_utc']] for c in ('wind_gen', 'solar_gen')},
        'heldout_method': 'Training-only response transforms, coding and smearing; realized held-out inputs; both past and future training days.',
        'paired_interval': '1999 circular 25-observation block resamples of paired held-out absolute losses; folds not refitted in each draw; descriptive uncertainty.',
        'no_fern_method': 'Fern removed from both training and evaluation; level transform recomputed on each reduced sample, unlike legacy runner fern_diagnostic.',
    })
    d = d[keep].sort_values('local_date').reset_index(drop=True)
    fitrows, cvrows, predictions, pairs = [], [], [], []
    for sample in ('all', 'exclude_fern'):
        ds = d if sample == 'all' else d[~d.local_date.between(*CONFIG['inference']['fern_window'])]
        for response in ('level', 'volatility'):
            cache = {}
            for model in FACTORS:
                s, f, _ = fit_surface(ds, model, response)
                fitrows.append({'sample': sample, 'response': response, 'model': model, 'n': s.n,
                                'r2': f.r2, 'adj_r2': f.adj_r2})
                for kind in ('week', 'month'):
                    p = heldout(ds, model, response, kind)
                    cache[model, kind] = p
                    key = {'sample': sample, 'response': response, 'model': model, 'holdout': kind}
                    cvrows.append({**key, **scores(p)})
                    predictions.append(p.assign(**key))
            for base in ('gross', 'wind_only', 'solar_only'):
                for kind in ('week', 'month'):
                    pairs.append({'sample': sample, 'response': response, 'baseline': base, 'candidate': 'net',
                                  'holdout': kind, **paired_mae(cache[base, kind], cache['net', kind])})
    fits, cv = pd.DataFrame(fitrows), pd.DataFrame(cvrows)
    fits.to_csv(out/'renewable_fits.csv', index=False)
    cv.to_csv(out/'renewable_holdouts.csv', index=False)
    pd.concat(predictions, ignore_index=True).to_csv(out/'renewable_predictions.csv', index=False)
    pd.DataFrame(pairs).to_csv(out/'renewable_paired_mae.csv', index=False)
    rows = []
    for (sample, response), g in fits.groupby(['sample', 'response'], sort=False):
        f = g.set_index('model')
        c = cv[(cv['sample'] == sample) & (cv.response == response)].set_index(['model', 'holdout'])
        rows.append({'sample': sample, 'response': response, 'n': int(f.loc['net', 'n']),
                     'gross_r2': f.loc['gross', 'r2'], 'net_r2': f.loc['net', 'r2'],
                     'r2_gain': f.loc['net', 'r2']-f.loc['gross', 'r2'],
                     **{f'{m}_{k}_mae': c.loc[(m, k), 'dollar_mae'] for m in ('gross', 'net') for k in ('week', 'month')}})
    pd.DataFrame(rows).to_csv(out/'renewable_comparison.csv', index=False)
    import matplotlib.pyplot as plt
    from figures import save, TEXT_WIDTH_IN
    fig, axes = plt.subplots(1, 2, figsize=(TEXT_WIDTH_IN, 2.8), constrained_layout=True)
    for i, (sample, title) in enumerate((('all', 'All matched days'), ('exclude_fern', 'Fern excluded'))):
        f = fits[(fits['sample'] == sample) & (fits.response == 'volatility')].set_index('model')
        vals = [f.loc[m, 'r2'] for m in ('gross', 'net')]
        axes[i].bar(['Gross load', 'Net load'], vals, color=['#64748b', '#0284c7'])
        for j, v in enumerate(vals):
            axes[i].text(j, v+.012, f'{v:.3f}', ha='center', fontsize=8)
        axes[i].set(title=f'{title} (n={int(f.loc["net", "n"])})', ylim=(0, .48), ylabel='R² of log daily spread SD')
    fig.suptitle('Optional system volatility: matched full quadratics', fontsize=9)
    save(fig, out/'figures', 'renewable_comparison')
    print(f'Renewable matched checks complete: {len(d)} days; original models retained.')
